import test from 'node:test';
import assert from 'node:assert/strict';
import {srgbToOklab,diagnosePattern,stats,generatePattern,DEFAULT_PALETTE} from '../frontend/src/engine.ts';
import {validateProject} from '../frontend/src/project.ts';
// Rounded reference values for sRGB primaries, consistent with Ottosson's published 2021 matrices.
// https://bottosson.github.io/posts/oklab/ ; constants, not generated by the function under test.
test('Oklab sRGB black white gray and primaries match reference tolerances',()=>{
 const cases:[number[],number[]][]=[[[0,0,0],[0,0,0]],[[255,255,255],[1,0,0]],[[128,128,128],[.5998708,0,0]],[[255,0,0],[.62795536,.22486306,.12584630]],[[0,255,0],[.86643961,-.23388757,.17949848]],[[0,0,255],[.45201372,-.03245698,-.31152815]]];
 for(const [rgb,expected] of cases){const actual=srgbToOklab(rgb);for(let i=0;i<3;i++)assert.ok(Math.abs(actual[i]-expected[i])<.00001,`${rgb} channel ${i}: ${actual[i]}`)}
});
test('same-grid optimization beats remapped frequency candidate and keeps material invariants',()=>{
 const w=64,h=64,rgba=new Uint8ClampedArray(w*h*4),mask=new Uint8Array(w*h).fill(1);
 const colors=['#F4F1EA','#E8E8E4','#DCE2E5','#D5E2E7','#C6DAE6','#AED1E4','#99C3DF','#B6B0EB','#F0C0A9','#EAB39E','#354B62','#202530'];
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const hex=colors[x<56?Math.floor(x/7):8+(x-56)%4],rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));rgba.set([...rgb,255],(y*w+x)*4)}
 // Hidden transparent cyan pixels must not enter sampling or add beads.
 for(let i=0;i<64;i++){rgba.set([0,255,255,0],i*4);mask[i]=0}
 for(const k of [8,16,32]){const d=diagnosePattern(rgba,w,h,mask,64,k),p=d.optimized;assert.ok(d.errors.optimized<=d.errors.legacyRemapped+1e-12);assert.equal(stats(p.cells).total,stats(d.legacy.cells).total);assert.ok(Object.keys(stats(p.cells).counts).length<=k);assert.ok(p.cells.every(c=>c===null||DEFAULT_PALETTE.some(v=>v.code===c)));assert.equal(new Set(p.palette.map(c=>c.code)).size,p.palette.length);assert.deepEqual(d.grid.values.map(v=>v===null),p.cells.map(v=>v===null));}
 const p=generatePattern(rgba,w,h,mask,64,16),v=validateProject({schemaVersion:2,pattern:p,points:[],locked:[],step:3,pitch:2.6,selectionMode:'whole',selectionDirty:false,tuning:{width:64,colors:16}});assert.equal(v.pattern?.algorithm,p.algorithm);assert.deepEqual(v.pattern?.cells,p.cells);assert.deepEqual(v.tuning,{width:64,colors:16});
});
